const f = "C:/Users/jjq21/Desktop/github/My-second-brain/50-知识/AI工具/_scripts/intel.mjs";
const old = `function clean(s) {
  return String(s || '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')`;
const neu = `function clean(s) {
  return String(s || '')
    .replace(/<!\\[CDATA\\[/g, '').replace(/\\]\\]>/g, '')  // hnrss 的 title 在 CDATA 里
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')`;
await tools.edit({ file_path: f, old_string: old, new_string: neu });
console.log("fixed CDATA handling in clean()");
